package ru.local.spbumailpilot;
import org.json.*;import java.util.*;import javax.mail.*;
public final class OfflinePrefetchTest {
 static void check(boolean v){if(!v)throw new AssertionError();}
 static JSONObject header(int uid)throws Exception{return new JSONObject().put("uid",String.valueOf(uid)).put("validity","7").put("folder","INBOX").put("seen",false).put("subject","Fixture").put("sender","Fixture");}
 public static void main(String[] args)throws Exception{
  JSONArray values=new JSONArray();for(int i=100;i>40;i--)values.put(header(i));JSONObject page=new JSONObject().put("messages",values).put("validity","7");List<JSONObject> refs=OfflinePrefetch.refs("INBOX",page);check(refs.size()==50&&refs.get(0).getString("uid").equals("51")&&refs.get(49).getString("uid").equals("100"));
  JSONArray invalid=new JSONArray().put(header(42)).put(header(42)).put(header(43).put("validity","8")).put(header(44).put("folder","Other")).put(header(0));check(OfflinePrefetch.refs("INBOX",new JSONObject().put("validity","7").put("messages",invalid)).size()==1);
  OfflineMailbox cache=new OfflineMailbox();cache.page("INBOX",0,new JSONObject().put("validity","7").put("messages",new JSONArray().put(header(42))));long before=cache.seenRevision("INBOX","42","7");cache.seen("INBOX","42","7",true);JSONObject body=new JSONObject().put("message",header(42)).put("text","Fixture");cache.prefetchedBody("INBOX","42","7",body,before);check(cache.body("INBOX","42","7").getJSONObject("message").getBoolean("seen"));check(!body.getJSONObject("message").getBoolean("seen"));
  ReadFlagTest.MemoryStore store=new ReadFlagTest.MemoryStore(Session.getInstance(new Properties()));MailReader reader=new MailReader();java.lang.reflect.Field field=MailReader.class.getDeclaredField("store");field.setAccessible(true);field.set(reader,store);reader.cachedBody("INBOX","42","7");check(!store.folder.message.isSet(Flags.Flag.SEEN)&&store.folder.getMode()==Folder.READ_ONLY);
  javax.mail.internet.MimeMessage forwarded=new javax.mail.internet.MimeMessage(Session.getInstance(new Properties())){public Object getContent()throws java.io.IOException,MessagingException{throw new java.io.IOException("Forwarded payload must not be fetched");}public java.io.InputStream getInputStream()throws java.io.IOException,MessagingException{throw new java.io.IOException("Forwarded payload must not be fetched");}};forwarded.setFrom("from@example.invalid");forwarded.setSubject("Fixture");forwarded.setHeader("Content-Type","message/rfc822");
  ReadFlagTest.MemoryFolder folder=new ReadFlagTest.MemoryFolder(store,Session.getInstance(new Properties())){public Message getMessageByUID(long uid){return forwarded;}};java.lang.reflect.Field inbox=MailReader.class.getDeclaredField("inbox");inbox.setAccessible(true);folder.open(Folder.READ_ONLY);inbox.set(reader,folder);JSONObject preview=reader.cachedBody("INBOX","42","7");check(preview.getString("text").isEmpty()&&preview.getJSONArray("attachments").length()==1);
  ReadFlagTest.MemoryStore rawStore=new ReadFlagTest.MemoryStore(Session.getInstance(new Properties())){public Folder getFolder(String name){return folder;}};
  javax.mail.internet.MimeMessage raw=new javax.mail.internet.MimeMessage(Session.getInstance(new Properties())){public Address[] getFrom()throws MessagingException{return new Address[]{new javax.mail.internet.InternetAddress("Имя\uFFFD <fixture@example.invalid>")};}};String expected="Виктор Олегович";byte[] utf8=expected.getBytes("UTF-8");raw.setHeader("From",MimeWordsTest.word("UTF-8","B",Arrays.copyOfRange(utf8,0,1))+" "+MimeWordsTest.word("UTF-8","B",Arrays.copyOfRange(utf8,1,utf8.length))+" <fixture@example.invalid>");raw.setText("Fixture");ReadFlagTest.MemoryFolder rawFolder=new ReadFlagTest.MemoryFolder(rawStore,Session.getInstance(new Properties())){public Message getMessageByUID(long uid){return raw;}};rawFolder.open(Folder.READ_ONLY);inbox.set(reader,rawFolder);check(reader.cachedBody("INBOX","42","7").getJSONObject("message").getString("sender").equals(expected));
  System.out.println("PASS: newest50 prefetch bounds/reverse retention, UID/UIDVALIDITY/folder/dedupe guards, actual read-only cached-body path and late preload preserves user read/unread changes.");
 }
}
